/**
 * Warp a point from the old 300 x 600 chart into image pixels (piecewise-linear landmarks: head, chin, shoulders, elbows,
 * hips, knees, ankles). Used to carry the joint markers and nerve lines onto the image. Approximate by design.
 */
const lerp = (pts: [number, number][], v: number) => {
  if (v <= pts[0]![0]) return pts[0]![1];
  for (let i = 1; i < pts.length; i += 1) {
    const [a, fa] = pts[i - 1]!; const [b, fb] = pts[i]!;
    if (v <= b) return fa + ((v - a) / (b - a)) * (fb - fa);
  }
  return pts[pts.length - 1]![1];
};
const Y_LM: [number, number][] = [[0, 22], [10, 40], [88, 172], [117, 250], [230, 440], [312, 610], [436, 830], [548, 1085], [600, 1170]];
const KX_BODY: [number, number][] = [[0, 1.8], [117, 2.2], [228, 2.1], [312, 2.05], [436, 2.6], [548, 3.1]];
const ARM_Y: [number, number][] = [[117, 262], [230, 440], [300, 545], [390, 650]];
const ARM_CX_OURS: [number, number][] = [[117, 84], [230, 68], [300, 62], [390, 59]];
const ARM_CX_IMG: [number, number][] = [[117, 322], [230, 266], [300, 222], [390, 190]];
export function warp(x: number, y: number): [number, number] {
  const dx = x - 150;
  const s = Math.sign(dx) || 1;
  const lx = s < 0 ? x : 300 - x; // work on the left half, mirror back
  if (Math.abs(dx) > 52 && y > 125 && y < 420) {
    const off = (lx - lerp(ARM_CX_OURS, y)) * 2.4;
    const ix = lerp(ARM_CX_IMG, y) + off;
    return [Math.round(s < 0 ? ix : 896 - ix), Math.round(lerp(ARM_Y, y))];
  }
  const k = lerp(KX_BODY, y);
  return [Math.round(448 + dx * k), Math.round(lerp(Y_LM, y))];
}
/** Warp every x,y pair of an absolute M/L/C path; mirror first when asked. */
export function warpPath(d: string, mirror = false): string {
  let i = 0;
  let px = 0;
  return d.replace(/-?\d+(?:\.\d+)?/g, (n) => {
    const v = Number(n);
    if (i++ % 2 === 0) { px = mirror ? 300 - v : v; return "\u0000"; }
    const [x, y] = warp(px, v);
    return `${x} ${y}`;
  }).replace(/\u0000[ ,]*/g, "");
}
